struct IView {                       // passive view contract
    virtual ~IView() = default;
    virtual std::string query() const = 0;
    virtual void showTotal(double total) = 0;
};
class Presenter {
    IView& view; Model& model;
public:
    Presenter(IView& v, Model& m) : view(v), model(m) {}
    void queryChanged() { view.showTotal(model.total(view.query())); }
};

class Presenter : public QObject {
    Q_OBJECT
public slots:
    void queryChanged(const QString &query) {
        emit totalChanged(model.total(query.toStdString()));
    }
};
QObject::connect(view, &StationWidget::queryChanged,
                 presenter, &Presenter::queryChanged);

struct View {                                  // contract as callables
    std::function<std::string()> query;
    std::function<void(double)> showTotal;
};
Presenter p{model};
View v{ [&]{ return entry.getText(); },
        [&](double t){ label.setText(fmt::format("{:.2f}", t)); } };
p.attach(v);          // presenter assigns/uses the callbacks
p.queryChanged();

